mapper.select:

SELECT
  count(*) totcnt
FROM
  ttokssaemdb.payment payment


    AND payment.branchid = #{session_branchid}


    AND payment.price LIKE #{likeQuery}

SELECT R1.* FROM( SELECT branch.branchid, branch.branchname, member.memberid, member.membername, goods.goodsid, goods.goodsname, payment.paymentid, payment.type, payment.startdate, payment.enddate, payment.price, DATE_FORMAT(payment.regdate, '%Y-%m-%d %H:%i:%s') regdate, payment.cancel, payment.canceluserid, DATE_FORMAT(payment.canceldate, '%Y-%m-%d %H:%i:%s') canceldate FROM ttokssaemdb.payment payment, ttokssaemdb.branch branch, ttokssaemdb.member member, ttokssaemdb.goods goods
AND payment.branchid = branch.branchid AND payment.memberid = member.memberid AND payment.goodsid = goods.goodsid
AND payment.branchid = #{session_branchid}
AND payment.price LIKE #{likeQuery}
payment.paymentid payment.regdate DESC ASC DESC
) R1
LIMIT ${length} OFFSET ${start}
